use filmcraft_render::{vfx::FxEnv,image::Image,effects::{apply,FxCtx}};use filmcraft_project::{EffectInstance,Param,ParamValue};use std::sync::Mutex;use serde_json::json;
struct Env {dt:Mutex<Option<f64>>,now:Option<u64>,invert:bool}
impl FxEnv for Env {
fn frame(&self,dt:f64,_:&EffectInstance)->Option<Image>{*self.dt.lock().unwrap()=Some(dt);if let Some(now)=self.now{let t=now as i64+(dt*1000000.).round()as i64;if !(0..1000000).contains(&t){return None;}Some(picture(t as u64,self.invert))}else{Some(Image::new(1,1))}}
fn source_frame(&self,_:f64,_:f32)->Option<Image>{None}fn track(&self,_:usize)->Option<Image>{None}
fn layer_to_output(&self)->filmcraft_geom::Affine{filmcraft_geom::Affine::IDENTITY}
fn clip_seconds(&self)->f64{100.}fn clip_offset(&self)->f64{0.}fn frame_rate(&self)->f64{24.}
fn media_timecode(&self)->String{String::new()}fn file_name(&self)->String{String::new()}fn sequence_name(&self)->String{String::new()}fn sequence_size(&self)->(u32,u32){(1,1)}fn source_size(&self)->(u32,u32){(1,1)}fn clip_key(&self)->u64{1}
}
fn picture(t:u64,invert:bool)->Image{let rgba:Vec<u8>=(0..24u64).flat_map(|i|{let k=t/10000;[(i*17+k*11)%256,(i*7+k*23)%256,(i*31+k*3)%256,255].map(|v|v as u8)}).collect();let px=rgba.chunks_exact(4).flat_map(|p|[filmcraft_color::srgb_to_linear(p[0]as f32/255.),filmcraft_color::srgb_to_linear(p[1]as f32/255.),filmcraft_color::srgb_to_linear(p[2]as f32/255.),1.]).collect();let mut img=Image{w:6,h:4,px};if invert{let e=filmcraft_project::effect_defs().iter().find(|e|e.id=="invert").unwrap().instance();let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);}img}
fn main(){let mut cases=vec![];for rate in [0.1f64,1.,12.,23.976,29.97,60.,99.] {for seconds in [0.,0.0000001,1./24.,2./24.,0.123456789,0.5,0.9999999,1.,3.141592653589793,100.] {let env=Env{dt:Mutex::new(None),now:None,invert:false};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="posterize_time").unwrap().instance();e.params.insert("rate".into(),Param::new(ParamValue::Float(rate)));let mut img=Image::new(1,1);let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:1.,seconds,timecode:"",clip_name:"",project:None,env:Some(&env),working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);cases.push(json!({"rate":rate,"seconds":seconds,"dt":*env.dt.lock().unwrap()}));}}let mut media=vec![];
for invert in [false,true]{for animated in [false,true]{for start in [0u64,250000,500000]{let mut frames=vec![];for index in 0..(1000000-start).div_ceil(100000){let tick=start+index*100000;let t=tick.min(500000)as f64/500000.;let rate=if animated{12.+12.*t}else{12.};let env=Env{dt:Mutex::new(None),now:Some(tick),invert};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="posterize_time").unwrap().instance();e.params.insert("rate".into(),Param::new(ParamValue::Float(rate)));let mut img=picture(tick,invert);let cx=FxCtx{t:filmcraft_time::Tick(tick as i64),px_scale:1.,seconds:tick as f64/1000000.,timecode:"",clip_name:"",project:None,env:Some(&env),working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);frames.push(img.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}media.push(json!({"localTick":start,"invert":invert,"animated":animated,"frames":frames}));}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
